    menos300: { slug: 'automatic-watches-under-300', h1: 'Automatic watches under €300', title: 'Automatic watches under €300: the best figures for the money', description: 'The automatic watches in the catalogue with an average indicative price under €300, compared.', criterio: 'watches whose average indicative price is under €300.' },
    menos500: { slug: 'automatic-watches-under-500', h1: 'Automatic watches under €500', title: 'Automatic watches under €500: compared in figures', description: 'Automatic watches under €500, with movement, power reserve, crystal and water resistance in one table.', criterio: 'watches whose average indicative price is under €500.' },
    menos1000: { slug: 'automatic-watches-under-1000', h1: 'Automatic watches under €1,000', title: 'Automatic watches under €1,000: Swiss and Japanese compared', description: 'Automatic watches under €1,000, from Seiko and Orient to Tissot and Hamilton, with all their figures.', criterio: 'watches whose average indicative price is under €1,000.' },
    zafiro600: { slug: 'sapphire-automatic-watches-under-600', h1: 'Sapphire automatics under €600', title: 'Automatic watches with sapphire crystal under €600', description: 'The least expensive automatic watches with sapphire crystal in the catalogue, with their movement and dimensions.', criterio: 'watches with sapphire crystal and an average indicative price under €600.' },
    zafiro: { slug: 'automatic-watches-with-sapphire-crystal', h1: 'Automatic watches with sapphire crystal', title: 'Automatic watches with sapphire crystal: every model', description: 'Every automatic watch in the catalogue with sapphire crystal, sorted by price.', criterio: 'watches with sapphire crystal, the most scratch-resistant.' },
    mm38: { slug: 'small-automatic-watches', h1: 'Automatic watches of 39.5 mm or less', title: 'Small automatic watches: 35 to 39.5 mm in diameter', description: 'Automatic watches up to 39.5 mm for slim wrists, with lug-to-lug and thickness compared.', criterio: 'watches up to 39.5 mm in diameter, from smallest to largest.' },
    mm40: { slug: 'automatic-watches-40mm', h1: '40 mm automatic watches', title: 'Automatic watches of 40 to 41 mm: the most versatile size', description: 'Automatic watches of 40 to 41 mm, the size that suits most wrists, compared in figures.', criterio: 'watches of 39.6 to 41 mm in diameter.' },
    grandes: { slug: 'large-automatic-watches', h1: 'Automatic watches of 42 mm or more', title: 'Large automatic watches: 42 to 45 mm', description: 'Automatic watches of 42 mm or more, with their lug-to-lug so you can tell whether they fit your wrist.', criterio: 'watches of 42 mm in diameter or more, from smallest to largest.' },
    reserva70: { slug: 'automatic-watches-80-hour-power-reserve', h1: 'Automatics with 70 hours of reserve or more', title: 'Automatic watches with a 70 or 80-hour power reserve', description: 'Automatic watches that survive a weekend off the wrist: 70 and 80 hours of power reserve.', criterio: 'watches with 70 hours of power reserve or more, sorted by reserve.' },
    wr200: { slug: 'automatic-watches-200m', h1: 'Automatic watches rated to 200 metres or more', title: 'Automatic watches with 200 or 300 metres of water resistance', description: 'Automatic watches with 200 metres of water resistance or more, for diving, compared in figures.', criterio: 'watches with 200 metres of water resistance or more.' },
    suizos: { slug: 'swiss-automatic-watches', h1: 'Swiss automatic watches', title: 'Swiss automatic watches under €1,500', description: 'Swiss automatic watches from Tissot, Hamilton, Mido and Glycine, with their movement and power reserve compared.', criterio: 'watches from Swiss brands.' },
    japoneses: { slug: 'japanese-automatic-watches', h1: 'Japanese automatic watches', title: 'Japanese automatic watches: Seiko, Orient and Citizen compared', description: 'Japanese automatic watches from Seiko, Orient and Citizen, with their in-house movements and every figure.', criterio: 'watches from Japanese brands.' },
